import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CZo9GF0W.js";const g=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1789060268000}'),r={name:"guide/getting-started.md"};function i(s,e,d,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Search <strong>Pitta</strong> in the Extensions view, or from a terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install-extension</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DipeshShrestha.pitta-db</span></span></code></pre></div><p>Pitta is also on <a href="https://open-vsx.org/extension/DipeshShrestha/pitta-db" target="_blank" rel="noreferrer">Open VSX</a> for VSCodium, Cursor, Windsurf and Gitpod.</p><p>Requires VS Code 1.90 or newer. There are no native modules and no separate runtime to install: one VSIX works on every platform, and the SQLite and PostgreSQL-grammar engines are WebAssembly shipped inside it.</p><div class="tip custom-block"><p class="custom-block-title">Running against a remote?</p><p>Pitta runs in the <strong>workspace</strong> extension host, so under Remote-SSH, WSL or a dev container the database connection is made <em>from the remote machine</em>. Install it on the remote, and read <a href="./remote">Remote development</a> before debugging a connection that &quot;works in psql&quot;.</p></div><h2 id="add-a-connection" tabindex="-1">Add a connection <a class="header-anchor" href="#add-a-connection" aria-label="Permalink to &quot;Add a connection&quot;">​</a></h2><ol><li>Click the Pitta icon in the activity bar, then <strong>+</strong> — or run <strong>Pitta: Add Connection</strong> from the command palette.</li><li>Pick the engine. The form redraws itself from that driver&#39;s own field list, so a MongoDB profile asks for a replica set and a Redis profile asks for a mode rather than for a database name that does not exist.</li><li>Fill in the connection. If you already have a URI, paste it into the host field — it is parsed and split across the form.</li><li><strong>Test Connection</strong> before saving. It resolves the secret, opens a real session, reads the server version, and closes it.</li></ol><p>The password goes to your OS keychain through VS Code&#39;s <code>SecretStorage</code>. It is never written to <code>settings.json</code>, a workspace file, or a log line, and it is never sent to the connection form itself — the form holds a reference, and the resolution happens in the extension host.</p><p>See <a href="./connections">Connections</a> for where a profile is stored, how to share one with a team, and every way a secret can be supplied.</p><h2 id="tag-the-environment" tabindex="-1">Tag the environment <a class="header-anchor" href="#tag-the-environment" aria-label="Permalink to &quot;Tag the environment&quot;">​</a></h2><p>Every connection is <code>dev</code>, <code>staging</code> or <code>prod</code>. This is not decoration:</p><ul><li>A <code>prod</code> connection is coloured everywhere it appears — the tree, the status bar, the results panel.</li><li>Destructive statements on <code>prod</code> require you to type the connection name back. A dialog you can dismiss with a click gets dismissed reflexively.</li><li><code>prod</code> is excluded from query history by default.</li></ul><p>Set it now rather than later. <a href="./safety">Safety and guards</a> is the full list of what changes.</p><h2 id="browse" tabindex="-1">Browse <a class="header-anchor" href="#browse" aria-label="Permalink to &quot;Browse&quot;">​</a></h2><p>Expand the connection → database → schema → table. The tree is lazy and paged: levels load as you open them, and a level with more objects than <code>pitta.explorer.pageSize</code> ends in a <strong>Show more</strong> entry rather than handing VS Code fifty thousand items.</p><p>Click a table, or run <strong>Open Data</strong>, to get the grid. See <a href="./data-grid">The data grid</a>.</p><h2 id="or-write-a-query" tabindex="-1">Or write a query <a class="header-anchor" href="#or-write-a-query" aria-label="Permalink to &quot;Or write a query&quot;">​</a></h2><p><strong>Pitta: New Query</strong> opens a file in the connected engine&#39;s own language — <code>.sql</code>, <code>.mongodb.js</code>, or <code>.redis</code>. The status bar at the bottom right shows which connection and database it runs against; click it to change.</p><p>Run the statement under the cursor with <code>Ctrl+Enter</code> / <code>Cmd+Enter</code>.</p><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Run the statement under the cursor</td><td><code>Ctrl+Enter</code> / <code>Cmd+Enter</code></td></tr><tr><td>Run the selection</td><td><code>Ctrl+Shift+Enter</code> / <code>Cmd+Shift+Enter</code></td></tr><tr><td>Run every statement in the file</td><td><code>Ctrl+Alt+Enter</code> / <code>Cmd+Alt+Enter</code></td></tr><tr><td>Cancel the running query</td><td><code>Ctrl+Shift+C</code> / <code>Cmd+Shift+C</code></td></tr></tbody></table><p>See <a href="./query-mode">Query mode</a>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./connections">Connections</a> — profiles, secrets, sharing, environments.</li><li><a href="/pitta-db/recipes/">Connection recipes</a> — a working setup per hosting provider.</li><li><a href="./data-grid">The data grid</a> — filtering, editing, the DML preview.</li><li><a href="./query-mode">Query mode</a> — completion, notebooks, history, saved queries.</li><li><a href="./safety">Safety and guards</a> — what Pitta refuses, and how to change it.</li><li><a href="./troubleshooting">Troubleshooting</a> — when it does not connect.</li></ul>',25)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
